sp_widget.client_script:
api.controller = function($scope) {

  /* =========================================================
     GATENOW · REIMBURSEMENTS · Client script

     Tabs, search and both modals run against data already on
     the page. The only server work is the embedded claim form,
     which is its own widget.
     ========================================================= */

  var c = this;

  c.query = '';
  c.tab   = 'all';
  c.open  = null;
  c.mtab  = 'payment';
  c.form  = false;

  c.tabs = [
    { key: 'all',       label: c.data.t.tabAll },
    { key: 'submitted', label: c.data.t.tabSubmitted },
    { key: 'review',    label: c.data.t.tabReview },
    { key: 'approved',  label: c.data.t.tabApproved },
    { key: 'paid',      label: c.data.t.tabPaid },
    { key: 'rejected',  label: c.data.t.tabRejected }
  ];

  /* Attachments only get a tab when there are some. An empty
     tab is a promise the record cannot keep. */
  c.modalTabs = [
    { key: 'payment',     label: c.data.t.mPayment,
      show: function() { return true; }, count: function() { return 0; } },
    { key: 'funding',     label: c.data.t.mFunding,
      show: function() { return true; }, count: function() { return 0; } },
    { key: 'computation', label: c.data.t.mComputation,
      show: function() { return true; }, count: function() { return 0; } },
    { key: 'alternate',   label: c.data.t.mAlternate,
      show: function() { return true; }, count: function() { return 0; } },
    { key: 'files',       label: c.data.t.mFiles,
      show: function(cl) { return cl.files.length > 0; },
      count: function(cl) { return cl.files.length; } }
  ];


  /* =====================================================
     LIST
     ===================================================== */

  function hit(cl, q) {
    return (
      (cl.number  || '').toLowerCase().indexOf(q) !== -1 ||
      (cl.project || '').toLowerCase().indexOf(q) !== -1 ||
      (cl.summary || '').toLowerCase().indexOf(q) !== -1 ||
      (cl.amountText || '').toLowerCase().indexOf(q) !== -1
    );
  }

  function matching() {
    var q = (c.query || '').trim().toLowerCase();

    return (c.data.claims || []).filter(function(cl) {
      if (c.tab !== 'all' && cl.status !== c.tab) return false;
      if (q && !hit(cl, q)) return false;
      return true;
    });
  }

  c.shown = function() { return matching(); };

  c.setTab = function(key) {
    if (c.tab === key) return;
    c.tab = key;
  };

  c.clearAll = function() {
    c.query = '';
    c.tab = 'all';
  };


  /* =====================================================
     DETAIL
     ===================================================== */

  c.openDetail = function(claim) {
    c.open = claim || null;
    /* always land on the first tab, so the tab from the last
       claim does not carry over to one with no attachments */
    c.mtab = 'payment';
  };

  c.closeDetail = function() { c.open = null; };

  /* only the boxes that were ticked. Six greyed out checkboxes
     are six things to read past on the way to the one that
     matters. */
  c.typeList = function(claim) {
    if (!claim) return [];

    var t = claim.types || {};
    var out = [];

    if (t.advance)       out.push(c.data.t.mAdvance);
    if (t.reimbursement) out.push(c.data.t.mReimbursement);
    if (t.final)         out.push(c.data.t.mFinal);
    if (t.partial)       out.push(c.data.t.mPartial);
    if (t.cash)          out.push(c.data.t.mCash);
    if (t.accrual)       out.push(c.data.t.mAccrual);

    return out;
  };

  c.fileSize = function(bytes) {
    if (!bytes) return '0 B';
    var k = 1024;
    var units = ['B', 'KB', 'MB', 'GB'];
    var i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 10) / 10 + ' ' + units[i];
  };


  /* =====================================================
     NEW CLAIM
     The form is its own widget, embedded rather than rebuilt.
     ===================================================== */

  c.openForm = function() {
    c.open = null;
    c.form = true;
  };

  c.closeForm = function() {
    c.form = false;
    /* the new claim will not be in the list until the page data
       is refetched, so ask for it */
    c.server.update();
  };

};

sp_widget.css:
/* =========================================================
   GATENOW · REIMBURSEMENTS
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   Same tokens as the other dashboard pages: navy, one accent
   blue, neutrals built from the navy at different opacities.

   THE ONE PLACE MONEY GETS ITS OWN COLOUR
   Paid is green. It is the only stage where cash has actually
   arrived, and on a page about being reimbursed that is the
   distinction worth carrying a colour. Everything before it is
   the accent blue at decreasing weight, which reads as a
   pipeline rather than as four unrelated states.

   TYPE
     tile      30  700  tabular   headline figures
     title     26  700  -0.03em   page title
     panel     15  600  -0.014em  panel headings
     amount    14  600  tabular   every figure in a table
     label     11  600   0.14em   uppercase small caps
   ========================================================= */

/* ---------- overflow overrides ---------- */

.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gn-layout { overflow: visible !important; }

/* The column holds the rail and lets it decide how wide to be.
   It used to carry a width through an inline ng-style, which is
   what put 140px of the rail on top of this page: the column
   reserved 96 while the rail draws 236.

   The transition moved to the rail, which is the element that
   actually changes width. Animating a wrapper that never
   resized was doing nothing. */

.aw-sidebar {
  flex: 0 0 auto;
  overflow: visible;
}


/* ---------- typeface ---------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- ink ---------- */
$b-navy:   #0a2540;
$b-ink-2:  rgba(10, 37, 64, 0.72);
$b-ink-3:  rgba(10, 37, 64, 0.54);
$b-ink-4:  rgba(10, 37, 64, 0.38);
$b-line:   rgba(10, 37, 64, 0.10);
$b-line-2: rgba(10, 37, 64, 0.06);
$b-tint:   rgba(10, 37, 64, 0.03);

/* ---------- accent ---------- */
$b-blue:    #1560e0;
$b-blue-dk: #0f4cbb;
$b-blue-1:  rgba(21, 96, 224, 0.08);
$b-blue-2:  rgba(21, 96, 224, 0.16);

/* ---------- state ---------- */
$b-green:   #1f8a63;
$b-green-1: rgba(31, 138, 99, 0.12);
$b-amber:   #a4741f;
$b-amber-1: rgba(164, 116, 31, 0.12);
$b-red:     #b8394a;
$b-red-1:   rgba(184, 57, 74, 0.10);

$b-white: #ffffff;
$b-page:  #f4f6fb;
$b-ease:  cubic-bezier(0.45, 0.05, 0.25, 1);

$b-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   PAGE
   ========================================================= */

.gn-layout {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  background: $b-page;
  font-family: $b-font;
}

/* Without min-width: 0 a flex child refuses to shrink below its
   own content width, and slides under the rail rather than
   narrowing. That is the usual cause of a stubborn overlap once
   the widths are right. */
.grb {
  flex: 1;
  min-width: 0;
  overflow: visible;
}

.grb {
  min-height: 100vh;
  padding: 28px 36px 68px;
  background: $b-page;
  font-family: $b-font;
  color: $b-navy;
  -webkit-font-smoothing: antialiased;
}

.grb *,
.grb *::before,
.grb *::after { box-sizing: border-box; }

.grb-right { text-align: right; }


/* =========================================================
   HEADER
   ========================================================= */

.grb-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  margin-bottom: 22px;
}

.grb-top__lead { min-width: 0; }

.grb .grb-top__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: $b-navy;
}

.grb .grb-top__sub {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
  margin: 7px 0 0;
  font-size: 13.5px;
  color: $b-ink-3;
}

.grb-top__scope { color: $b-blue-dk; font-weight: 600; }

.grb-live {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: $b-green;
  box-shadow: 0 0 0 3px $b-green-1;
  flex-shrink: 0;
}

.grb-top__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.grb-search {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 330px;
  height: 42px;
  padding: 0 12px 0 14px;
  margin: 0;
  border: 1px solid $b-line;
  border-radius: 11px;
  background: $b-white;
  font-weight: 400;
  transition: border-color 0.4s $b-ease, box-shadow 0.4s $b-ease;
}

.grb-search:focus-within {
  border-color: rgba(21, 96, 224, 0.45);
  box-shadow: 0 0 0 3px $b-blue-1;
}

.grb-search__icon {
  font-size: 13px;
  color: $b-ink-4;
  flex-shrink: 0;
}

.grb-search__field {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  font-family: inherit;
  font-size: 14px;
  color: $b-navy;
}

.grb-search__field::placeholder { color: $b-ink-4; }

.grb-search__clear {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: $b-tint;
  color: $b-ink-3;
  font-size: 10px;
  cursor: pointer;
  flex-shrink: 0;
}

.grb-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: $b-blue;
  color: $b-white;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.03em;
  flex-shrink: 0;
  box-shadow: 0 6px 16px rgba(21, 96, 224, 0.28);
}


/* =========================================================
   NOTHING YET
   ========================================================= */

.grb-blank {
  max-width: 540px;
  margin: 70px auto;
  padding: 52px 34px 46px;
  border: 1px solid $b-line;
  border-radius: 18px;
  background: $b-white;
  text-align: center;
}

.grb-blank__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin: 0 auto 20px;
  border-radius: 50%;
  background: $b-blue-1;
  color: $b-blue;
  font-size: 22px;
}

.grb .grb-blank__title {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $b-navy;
}

.grb .grb-blank__text {
  max-width: 48ch;
  margin: 11px auto 24px;
  font-size: 15px;
  line-height: 1.64;
  color: $b-ink-3;
}


/* =========================================================
   TILES
   ========================================================= */

.grb-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.grb-tile {
  position: relative;
  padding: 20px 22px 22px;
  border: 1px solid $b-line;
  border-radius: 16px;
  background: $b-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: transform 0.5s $b-ease, box-shadow 0.5s $b-ease;
}

.grb-tile:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 32px rgba(10, 37, 64, 0.08);
}

.grb-tile__rule {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  background: $b-blue-2;
  transform-origin: left center;
}

/* paid is the only tile where money has actually landed */
.grb-tile--paid .grb-tile__rule { background: rgba(31, 138, 99, 0.34); }
.grb-tile.is-alert .grb-tile__rule { background: rgba(164, 116, 31, 0.34); }

.grb .grb-tile__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $b-ink-4;
}

.grb .grb-tile__value {
  margin: 12px 0 0;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.034em;
  font-variant-numeric: tabular-nums;
  color: $b-navy;
}

.grb-tile--paid .grb-tile__value { color: $b-green; }

.grb .grb-tile__note {
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.5;
  color: $b-ink-3;
}

.grb-tile.is-alert .grb-tile__note {
  color: $b-amber;
  font-weight: 500;
}


/* =========================================================
   PANELS
   ========================================================= */

.grb-panel {
  padding: 22px 24px 24px;
  margin-bottom: 16px;
  border: 1px solid $b-line;
  border-radius: 16px;
  background: $b-white;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.grb-panels {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
  gap: 16px;
  margin-bottom: 16px;
}

.grb-panels .grb-panel { margin-bottom: 0; }

.grb-panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin-bottom: 22px;
}

.grb .grb-panel__title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.014em;
  color: $b-navy;
}

.grb .grb-panel__hint {
  margin: 5px 0 0;
  max-width: 62ch;
  font-size: 12.5px;
  line-height: 1.55;
  color: $b-ink-4;
}

.grb .grb-panel__empty {
  margin: 0;
  padding: 30px 0 8px;
  font-size: 13.5px;
  color: $b-ink-4;
}

.grb-reject {
  padding: 6px 12px;
  border: 1px solid rgba(184, 57, 74, 0.26);
  border-radius: 8px;
  background: $b-red-1;
  font-size: 12.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $b-red;
  white-space: nowrap;
}

.grb .grb-key {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.grb .grb-key li {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: $b-ink-3;
}

.grb-key__box {
  width: 12px;
  height: 12px;
  border-radius: 4px;
  flex-shrink: 0;
}

.grb-key__box--claimed { background: $b-blue; }
.grb-key__box--paid    { background: $b-green; }


/* =========================================================
   PIPELINE
   Four stages in the order money moves. Blue lightens along the
   run and paid turns green, so the row reads as a journey with
   an end rather than four unrelated states.
   ========================================================= */

.grb-pipe {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
}

.grb-stage { min-width: 0; }

.grb-stage__top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
}

.grb-stage__label {
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: -0.008em;
  color: $b-ink-2;
}

.grb-stage__count {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $b-ink-4;
}

.grb-stage__track {
  display: block;
  height: 8px;
  border-radius: 999px;
  background: $b-tint;
  overflow: hidden;
}

.grb-stage__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  transform-origin: left center;
}

.grb-stage--submitted .grb-stage__fill { background: rgba(21, 96, 224, 0.42); }
.grb-stage--review .grb-stage__fill    { background: rgba(21, 96, 224, 0.62); }
.grb-stage--approved .grb-stage__fill  { background: $b-blue; }
.grb-stage--paid .grb-stage__fill      { background: $b-green; }

.grb-stage__value {
  display: block;
  margin-top: 11px;
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.026em;
  font-variant-numeric: tabular-nums;
  color: $b-navy;
}

.grb-stage--paid .grb-stage__value { color: $b-green; }

/* a stage with nothing in it is still part of the run, it just
   steps back rather than disappearing */
.grb-stage.is-empty .grb-stage__label,
.grb-stage.is-empty .grb-stage__value { color: $b-ink-4; }


/* =========================================================
   CLAIMED AGAINST PAID
   ========================================================= */

.grb-chart {
  display: flex;
  gap: 14px;
}

.grb-chart__axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 168px;
  flex-shrink: 0;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: $b-ink-4;
  text-align: right;
}

.grb-chart__plot {
  position: relative;
  flex: 1;
  min-width: 0;
  height: 168px;
}

.grb-chart__line {
  position: absolute;
  right: 0;
  left: 0;
  top: 0;
  height: 1px;
  background: $b-line-2;
}

.grb-chart__line--mid  { top: 50%; }
.grb-chart__line--base { top: auto; bottom: 0; background: $b-line; }

.grb-chart__cols {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
}

.grb-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
  min-width: 0;
  flex: 1;
}

.grb-col__pair {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 5px;
  width: 100%;
  height: 100%;
  padding-bottom: 22px;
}

/* min-height so a small month is still a visible mark rather
   than a gap you have to interpret */
.grb-col__bar {
  display: block;
  width: 16px;
  min-height: 2px;
  border-radius: 4px 4px 0 0;
  transform-origin: bottom center;
}

.grb-col__bar--claimed { background: $b-blue; }
.grb-col__bar--paid    { background: $b-green; }

.grb-col__label {
  position: absolute;
  bottom: 0;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: $b-ink-4;
}


/* =========================================================
   PAYMENT TYPES
   ========================================================= */

.grb-types {
  display: grid;
  gap: 13px;
}

.grb-type {
  display: grid;
  grid-template-columns: 104px minmax(0, 1fr) 30px;
  align-items: center;
  gap: 14px;
}

.grb-type__label {
  font-size: 13px;
  color: $b-ink-2;
}

.grb-type__track {
  display: block;
  height: 7px;
  border-radius: 999px;
  background: $b-tint;
  overflow: hidden;
}

.grb-type__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: $b-blue;
  transform-origin: left center;
}

/* the basis pair is a different kind of fact from the payment
   pair, so it is drawn a shade back */
.grb-type--cash .grb-type__fill,
.grb-type--accrual .grb-type__fill { background: rgba(21, 96, 224, 0.45); }

.grb-type__count {
  text-align: right;
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $b-navy;
}

.grb-type.is-zero .grb-type__label,
.grb-type.is-zero .grb-type__count { color: $b-ink-4; }


/* =========================================================
   TABLE
   ========================================================= */

.grb-block {
  border: 1px solid $b-line;
  border-radius: 16px;
  background: $b-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.grb-block__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px 24px;
  padding: 20px 24px;
}

.grb .grb-block__title {
  margin: 0;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.018em;
  color: $b-navy;
}

.grb .grb-block__hint {
  margin: 4px 0 0;
  font-size: 12.5px;
  color: $b-ink-4;
}

.grb-block__right {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.grb-tabs {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 4px;
  border: 1px solid $b-line;
  border-radius: 11px;
  background: $b-page;
}

.grb-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: $b-ink-3;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.4s $b-ease, color 0.4s $b-ease, border-color 0.4s $b-ease;
}

.grb-tab:hover { color: $b-navy; }

.grb-tab.is-on {
  background: $b-white;
  border-color: $b-line;
  color: $b-navy;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.06);
}

.grb-tab__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: $b-ink-4;
  flex-shrink: 0;
}

.grb-tab__dot--all       { background: transparent; box-shadow: inset 0 0 0 1.5px rgba(10, 37, 64, 0.24); }
.grb-tab__dot--submitted { background: rgba(21, 96, 224, 0.42); }
.grb-tab__dot--review    { background: rgba(21, 96, 224, 0.7); }
.grb-tab__dot--approved  { background: $b-blue; }
.grb-tab__dot--paid      { background: $b-green; }
.grb-tab__dot--rejected  { background: $b-red; }

.grb-tab__count {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $b-ink-4;
}

.grb-table { min-width: 0; }

.grb-table__head,
.grb-row {
  display: grid;
  grid-template-columns: 148px minmax(0, 1fr) 186px 132px 140px 96px;
  align-items: center;
  gap: 0 22px;
  padding: 0 24px;
}

.grb-table__head {
  height: 42px;
  border-top: 1px solid $b-line-2;
  border-bottom: 1px solid $b-line-2;
  background: rgba(10, 37, 64, 0.015);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: $b-ink-4;
}

/* the amount column right aligns on both rows, with real space
   before the state column so the seam does not read as one
   broken column */
.grb-table__head > :nth-child(4),
.grb-row > :nth-child(4) {
  text-align: right;
  padding-right: 10px;
}

.grb-table__head > :nth-child(5),
.grb-row > :nth-child(5) { padding-left: 22px; }

.grb-table__head > :nth-child(6),
.grb-row > :nth-child(6) {
  text-align: right;
  justify-self: end;
}

.grb-row {
  min-height: 66px;
  padding-top: 13px;
  padding-bottom: 13px;
  border-bottom: 1px solid $b-line-2;
  font-size: 14px;
  color: $b-ink-2;
  transition: background 0.4s $b-ease;
}

.grb-row:last-child { border-bottom: 0; }

.grb-row:hover { background: rgba(21, 96, 224, 0.025); }

.grb-cell--ref {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.grb-cell__top {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $b-navy;
}

.grb-cell__sub {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $b-ink-4;
}

.grb-cell--name {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $b-navy;
}

.grb-cell--date {
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: $b-ink-3;
}

.grb-cell--num {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.012em;
  font-variant-numeric: tabular-nums;
  color: $b-navy;
  white-space: nowrap;
}

.grb-row--paid .grb-cell--num { color: $b-green; }
.grb-row--rejected .grb-cell--num { color: $b-ink-4; }

.grb-cell--date.is-blank {
  font-style: italic;
  color: $b-ink-4;
}

.grb-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 4px 11px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.grb-pill__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.grb-pill--wait { background: $b-tint;    color: $b-ink-3; }
.grb-pill--ok   { background: $b-blue-1;  color: $b-blue-dk; }
.grb-pill--good { background: $b-green-1; color: $b-green; }
.grb-pill--bad  { background: $b-red-1;   color: $b-red; }

.grb-pill--wait .grb-pill__dot { background: $b-ink-4; }
.grb-pill--ok .grb-pill__dot   { background: $b-blue; }
.grb-pill--good .grb-pill__dot { background: $b-green; }
.grb-pill--bad .grb-pill__dot  { background: $b-red; }


/* =========================================================
   BUTTONS
   ========================================================= */

.grb-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 17px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.4s $b-ease, border-color 0.4s $b-ease, color 0.4s $b-ease;
}

.grb-btn--sm {
  height: 34px;
  padding: 0 14px;
  font-size: 13px;
}

.grb-btn--primary {
  background: $b-blue;
  border-color: $b-blue;
  color: $b-white;
}

.grb-btn--primary:hover,
.grb-btn--primary:focus {
  background: $b-blue-dk;
  border-color: $b-blue-dk;
  color: $b-white;
}

.grb-btn--ghost {
  border-color: $b-line;
  color: $b-ink-2;
}

.grb-btn--ghost:hover,
.grb-btn--ghost:focus {
  border-color: $b-blue-2;
  color: $b-blue-dk;
}

.grb-btn:focus-visible,
.grb-tab:focus-visible,
.grb-mtab:focus-visible,
.grb-search__clear:focus-visible {
  outline: 2px solid $b-blue;
  outline-offset: 2px;
}


/* =========================================================
   NO MATCH
   ========================================================= */

.grb-nomatch {
  padding: 58px 24px;
  text-align: center;
}

.grb .grb-nomatch__title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.018em;
  color: $b-navy;
}

.grb .grb-nomatch__text {
  max-width: 44ch;
  margin: 9px auto 18px;
  font-size: 14.5px;
  line-height: 1.6;
  color: $b-ink-3;
}


/* =========================================================
   MODAL
   ========================================================= */

.grb-modal {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1050;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 38px 20px;
  overflow-y: auto;
  background: rgba(10, 37, 64, 0.42);
  -webkit-backdrop-filter: blur(3px);
  backdrop-filter: blur(3px);
}

.grb-modal__panel {
  width: 100%;
  max-width: 760px;
  border-radius: 18px;
  background: $b-white;
  box-shadow: 0 30px 80px rgba(10, 37, 64, 0.3);
  overflow: hidden;
}

.grb-modal__panel--wide { max-width: 1040px; }

.grb-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 26px 20px;
}

.grb-modal__lead { min-width: 0; }

.grb-modal__ref {
  display: block;
  margin-bottom: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: $b-ink-4;
}

.grb .grb-modal__title {
  margin: 0 0 11px;
  font-size: 21px;
  font-weight: 700;
  line-height: 1.26;
  letter-spacing: -0.026em;
  color: $b-navy;
}

/* the amount sits in the header, because it is the reason
   anyone opened the record */
.grb-modal__amount {
  text-align: right;
  margin-left: auto;
  padding-right: 8px;
  flex-shrink: 0;
}

.grb-modal__amountLabel {
  display: block;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: $b-ink-4;
}

.grb-modal__amountValue {
  display: block;
  margin-top: 6px;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: $b-navy;
}

.grb-modal__x {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border: 1px solid $b-line;
  border-radius: 10px;
  background: transparent;
  color: $b-ink-3;
  font-size: 13px;
  cursor: pointer;
  transition: border-color 0.4s $b-ease, color 0.4s $b-ease;
}

.grb-modal__x:hover {
  border-color: $b-blue-2;
  color: $b-blue-dk;
}

.grb-mtabs {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 0 26px;
  border-bottom: 1px solid $b-line-2;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.grb-mtab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 42px;
  padding: 0 14px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: $b-ink-3;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  flex-shrink: 0;
  transition: color 0.4s $b-ease, border-color 0.4s $b-ease;
}

.grb-mtab:hover { color: $b-navy; }

.grb-mtab.is-on {
  border-bottom-color: $b-blue;
  color: $b-blue-dk;
  font-weight: 600;
}

.grb-mtab__n {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $b-ink-4;
}

.grb-modal__body {
  max-height: 60vh;
  padding: 22px 26px;
  overflow-y: auto;
}

/* the embedded claim form brings its own layout, so this only
   gives it room */
.grb-modal__body--form {
  max-height: 78vh;
  padding: 0;
}

.grb .grb-kvs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 30px;
  margin: 0;
  padding: 0;
}

.grb .grb-kvs--one   { grid-template-columns: minmax(0, 1fr); }
.grb .grb-kvs--three { grid-template-columns: repeat(3, minmax(0, 1fr)); }

.grb-kv { min-width: 0; }

.grb .grb-kv dt {
  margin: 0 0 4px;
  font-size: 12px;
  line-height: 1.45;
  color: $b-ink-4;
}

.grb .grb-kv dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.5;
  color: $b-navy;
  word-break: break-word;
}

.grb .grb-kv dd.grb-kv--num { font-variant-numeric: tabular-nums; }

.grb .grb-kv dd.grb-kv--lead {
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $b-green;
}

.grb .grb-kv dd.is-blank {
  font-weight: 400;
  font-style: italic;
  color: $b-ink-4;
}

.grb .grb-sub {
  margin: 26px 0 14px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $b-blue;
}

/* ticked payment types only */
.grb .grb-flags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.grb .grb-flags li {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  border: 1px solid $b-blue-2;
  border-radius: 999px;
  background: $b-blue-1;
  font-size: 13px;
  font-weight: 600;
  color: $b-blue-dk;
}

.grb .grb-flags li i { font-size: 10px; }

/* =========================================================
   THE ARITHMETIC
   Laid out in the order the form performs it, with the
   subtractions marked, so the total at the bottom can be
   followed rather than taken on trust.
   ========================================================= */

.grb .grb-calc {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
}

.grb-calc__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 20px;
  padding: 11px 0;
  border-bottom: 1px solid $b-line-2;
}

.grb .grb-calc__row dt {
  margin: 0;
  font-size: 13.5px;
  color: $b-ink-2;
}

.grb .grb-calc__row dd {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: $b-navy;
}

/* a line that is taken away rather than added */
.grb-calc__row.is-minus dt { padding-left: 14px; }

.grb .grb-calc__row.is-minus dd {
  color: $b-ink-3;
}

.grb .grb-calc__row.is-minus dd::before {
  content: "\2212 ";
  color: $b-ink-4;
}

.grb-calc__row.is-sum {
  background: $b-tint;
}

.grb .grb-calc__row.is-sum dt {
  font-weight: 600;
  color: $b-navy;
}

.grb-calc__row.is-total {
  padding: 15px 0;
  border-bottom: 0;
  border-top: 2px solid $b-navy;
}

.grb .grb-calc__row.is-total dt {
  font-size: 14px;
  font-weight: 700;
  color: $b-navy;
}

.grb .grb-calc__row.is-total dd {
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $b-green;
}

.grb-calc__row.is-sum dt,
.grb-calc__row.is-sum dd { padding: 0 12px; }

.grb .grb-empty {
  margin: 0;
  padding: 26px 0;
  font-size: 13.5px;
  color: $b-ink-4;
}

.grb-prose { margin-top: 22px; }

.grb .grb-prose__label {
  margin: 0 0 6px;
  font-size: 12px;
  color: $b-ink-4;
}

.grb .grb-prose__text {
  margin: 0;
  max-width: 72ch;
  font-size: 14.5px;
  line-height: 1.7;
  color: $b-ink-2;
  white-space: pre-line;
}

.grb .grb-files {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.grb-file {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 13px;
  border: 1px solid $b-line;
  border-radius: 11px;
}

.grb-file__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: $b-blue-1;
  color: $b-blue;
  font-size: 14px;
  flex-shrink: 0;
}

.grb-file__body {
  flex: 1;
  min-width: 0;
}

.grb-file__name {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 14px;
  font-weight: 500;
  color: $b-navy;
}

.grb-file__size {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $b-ink-4;
}

.grb-file__dl {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1px solid $b-line;
  border-radius: 9px;
  color: $b-ink-3;
  font-size: 13px;
  flex-shrink: 0;
  text-decoration: none;
  transition: border-color 0.4s $b-ease, color 0.4s $b-ease;
}

.grb-file__dl:hover,
.grb-file__dl:focus {
  border-color: $b-blue-2;
  color: $b-blue-dk;
  text-decoration: none;
}

.grb-modal__foot {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 16px 26px;
  border-top: 1px solid $b-line-2;
  background: $b-page;
}


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes grbRise {
    from { opacity: 0; transform: translateY(14px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes grbDrawX {
    from { transform: scaleX(0); }
    to   { transform: scaleX(1); }
  }

  @keyframes grbGrowY {
    from { transform: scaleY(0); }
    to   { transform: scaleY(1); }
  }

  @keyframes grbFade {
    from { opacity: 0; }
    to   { opacity: 1; }
  }

  @keyframes grbPanelIn {
    from { opacity: 0; transform: translateY(16px) scale(0.99); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
  }

  .grb-top   { animation: grbRise 0.6s $b-ease backwards; }
  .grb-blank { animation: grbRise 0.6s $b-ease 0.08s backwards; }
  .grb-tile  { animation: grbRise 0.62s $b-ease backwards; }

  .grb-tile--claimed { animation-delay: 0.06s; }
  .grb-tile--paid    { animation-delay: 0.12s; }
  .grb-tile--waiting { animation-delay: 0.18s; }
  .grb-tile--speed   { animation-delay: 0.24s; }

  .grb-tile__rule { animation: grbDrawX 0.7s $b-ease 0.3s backwards; }

  .grb-panel { animation: grbRise 0.62s $b-ease 0.28s backwards; }
  .grb-block { animation: grbRise 0.62s $b-ease 0.36s backwards; }

  /* the pipeline fills left to right, in the order money moves */
  .grb-stage__fill { animation: grbDrawX 0.8s $b-ease backwards; }

  .grb-stage--submitted .grb-stage__fill { animation-delay: 0.38s; }
  .grb-stage--review .grb-stage__fill    { animation-delay: 0.46s; }
  .grb-stage--approved .grb-stage__fill  { animation-delay: 0.54s; }
  .grb-stage--paid .grb-stage__fill      { animation-delay: 0.62s; }

  .grb-col__bar { animation: grbGrowY 0.6s $b-ease backwards; }

  .grb-col--n1 .grb-col__bar { animation-delay: 0.42s; }
  .grb-col--n2 .grb-col__bar { animation-delay: 0.48s; }
  .grb-col--n3 .grb-col__bar { animation-delay: 0.54s; }
  .grb-col--n4 .grb-col__bar { animation-delay: 0.60s; }
  .grb-col--n5 .grb-col__bar { animation-delay: 0.66s; }
  .grb-col--n6 .grb-col__bar { animation-delay: 0.72s; }

  .grb-type__fill { animation: grbDrawX 0.7s $b-ease 0.46s backwards; }

  /* replays on every tab change, because ng-repeat rebuilds its
     nodes and the keyframe starts again with them */
  .grb-row { animation: grbRise 0.42s $b-ease backwards; }

  .grb-row--n1  { animation-delay: 0.02s; }
  .grb-row--n2  { animation-delay: 0.05s; }
  .grb-row--n3  { animation-delay: 0.08s; }
  .grb-row--n4  { animation-delay: 0.11s; }
  .grb-row--n5  { animation-delay: 0.14s; }
  .grb-row--n6  { animation-delay: 0.17s; }
  .grb-row--n7  { animation-delay: 0.20s; }
  .grb-row--n8  { animation-delay: 0.23s; }
  .grb-row--n9  { animation-delay: 0.26s; }
  .grb-row--n10 { animation-delay: 0.29s; }

  .grb-modal { animation: grbFade 0.28s $b-ease backwards; }
  .grb-modal__panel { animation: grbPanelIn 0.4s $b-ease 0.04s backwards; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1320px) {

  .grb { padding: 26px 24px 60px; }

  .grb-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .grb-panels { grid-template-columns: minmax(0, 1fr); }

  .grb-table__head,
  .grb-row {
    grid-template-columns: 128px minmax(0, 1fr) 156px 118px 128px 88px;
    gap: 0 16px;
    padding: 0 18px;
  }
}

@media (max-width: 1024px) {

  .grb-pipe {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px 24px;
  }
}

@media (max-width: 900px) {

  .grb { padding: 22px 16px 52px; }

  .grb-top__right {
    width: 100%;
    order: 2;
  }

  .grb-search { width: 100%; }

  .grb-tiles { grid-template-columns: minmax(0, 1fr); }

  .grb-pipe { grid-template-columns: minmax(0, 1fr); }

  .grb-block__head { align-items: stretch; flex-direction: column; }

  .grb-block__right { justify-content: space-between; }

  .grb-tabs {
    flex-wrap: nowrap;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .grb-tab { flex-shrink: 0; }

  /* six columns at this width leaves four of them two
     characters wide, so rows stack instead */
  .grb-table__head { display: none; }

  .grb-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
    padding: 16px 18px;
  }

  .grb-cell--name { grid-column: 1 / -1; }

  .grb-row > span::before {
    content: attr(data-label);
    display: block;
    margin-bottom: 4px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: $b-ink-4;
  }

  .grb-cell--ref::before,
  .grb-cell--name::before { display: none; }

  .grb-table__head > :nth-child(4),
  .grb-row > :nth-child(4) { text-align: left; padding-right: 0; }

  .grb-table__head > :nth-child(5),
  .grb-row > :nth-child(5) { padding-left: 0; }

  .grb-row > .grb-right {
    text-align: left;
    justify-self: start;
  }

  .grb .grb-kvs,
  .grb .grb-kvs--three { grid-template-columns: minmax(0, 1fr); }

  .grb-modal { padding: 16px 12px; }
  .grb-modal__head {
    flex-wrap: wrap;
    padding: 20px 18px 14px;
  }
  .grb-modal__amount { text-align: left; margin-left: 0; }
  .grb-mtabs { padding: 0 18px; }
  .grb-modal__body { padding: 18px; max-height: 66vh; }
  .grb-modal__foot { padding: 14px 18px; }

  .grb-calc__row {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .grb * { transition: none; }
  .grb-tile:hover { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · REIMBURSEMENTS
     Service Portal widget · Server script

     WHAT CHANGED FROM THE VERSION IN USE

     1. GlideRecordSecure on the claim table. The old script
        used a plain GlideRecord, which reads past the ACLs.

     2. Claimed to date excluded rejected claims. A rejected
        claim is not money in flight, and counting it inflated
        both the headline figure and the paid percentage that
        divides into it.

     3. Paid percentage is now of what was approved or paid,
        not of everything ever submitted. Dividing by claims
        that were rejected or are still in review makes the
        number drift down for reasons that are nobody's fault.

     4. Average days to payment was calculated and then never
        shown. It is the single most useful number on the page
        for an applicant deciding whether to chase, so it is a
        tile now.

     5. The status list is Submitted, In review, Approved,
        Rejected, Paid. There is no Returned, so the branch
        handling it was dead code and is gone.

     Fields are taken from the four form tabs: type of payment,
     funding and reporting, computation, and the alternate
     computation for advances.
     ========================================================= */

  var CLAIM     = 'x_enno_gatenow_reimbursement';
  var APPLICANT = 'x_enno_gatenow_service_applicants';
  var PROJECT   = 'x_enno_gatenow_project';

  var me = gs.getUserID();

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }

  function lower(v) {
    return (v === null || v === undefined) ? '' : ('' + v).toLowerCase().trim();
  }

  function toGDT(value) {
    if (!value) return null;
    var s = '' + value;
    if (s.length === 10) s += ' 00:00:00';
    try { return new GlideDateTime(s); } catch (e) { return null; }
  }

  function fmtDate(value) {
    var g = toGDT(value);
    if (!g) return '';
    try { return g.getDate().getByFormat('d MMM yyyy'); } catch (e) { return '' + value; }
  }

  /* currency fields arrive as "USD;1000" or a bare number */
  function num(raw) {
    if (raw === null || raw === undefined || raw === '') return 0;
    var s = '' + raw;
    if (s.indexOf(';') !== -1) s = s.split(';').pop();
    var n = parseFloat(s);
    return isNaN(n) ? 0 : n;
  }

  function commas(n) {
    var s = '' + Math.round(n);
    var out = '';
    var c = 0;
    for (var i = s.length - 1; i >= 0; i--) {
      out = s.charAt(i) + out;
      c++;
      if (c % 3 === 0 && i > 0) out = ',' + out;
    }
    return out;
  }

  function money(n)  { return n ? '$' + commas(n) : '$0'; }

  function short(n) {
    if (!n) return '$0';
    if (n >= 1000000) return '$' + (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
    if (n >= 1000)    return '$' + Math.round(n / 1000) + 'K';
    return '$' + commas(n);
  }

  function pick(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next */ }
    }
    return '';
  }

  function money2(gr, names) { return num(pick(gr, names)); }

  function bool(gr, name) {
    try {
      if (!gr.isValidField(name)) return false;
      var v = '' + gr.getValue(name);
      return v === 'true' || v === '1';
    } catch (e) { return false; }
  }

  function text(raw) {
    if (!raw) return '';
    return ('' + raw)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n\n')
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/\s+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }


  /* ---------- chrome ---------- */
  data.sideBar = $sp.getWidget(opt('sidebar_widget', 'sidebar'));

  /* the existing claim form is kept rather than rebuilt. It
     carries twenty five federal fields and four tabs, and there
     is no version of rewriting that improves on it. */
  data.claimForm = $sp.getWidget(opt('form_widget', 'reimbursement_form'));

  var u = gs.getUser();
  var fn = u.getFirstName() || '';
  var ln = u.getLastName() || '';
  data.userInitials = (fn.charAt(0) + ln.charAt(0)).toUpperCase() ||
                      (u.getDisplayName() || 'U').substring(0, 2).toUpperCase();


  /* ============================================================
     STATUS
     ============================================================ */

  var STATUS = {
    'submitted': { key: 'submitted', label: gs.getMessage('Submitted'),  stage: 1, tone: 'wait' },
    'in review': { key: 'review',    label: gs.getMessage('In review'),  stage: 2, tone: 'wait' },
    'approved' : { key: 'approved',  label: gs.getMessage('Approved'),   stage: 3, tone: 'ok'   },
    'paid'     : { key: 'paid',      label: gs.getMessage('Paid'),       stage: 4, tone: 'good' },
    'rejected' : { key: 'rejected',  label: gs.getMessage('Rejected'),   stage: 0, tone: 'bad'  }
  };

  function statusOf(raw) {
    var v = lower(raw);
    return STATUS[v] || STATUS['submitted'];
  }


  /* ============================================================
     SCOPE
     ============================================================ */

  var projectIds = [];
  var projectName = {};

  try {

    var applicantIds = [];
    var ap = new GlideRecordSecure(APPLICANT);
    ap.addQuery('user', me);
    ap.query();
    while (ap.next()) applicantIds.push(ap.getUniqueValue());

    if (applicantIds.length) {
      var pj = new GlideRecordSecure(PROJECT);
      pj.addQuery('applicant', 'IN', applicantIds.join(','));
      pj.query();
      while (pj.next()) {
        var pid = pj.getUniqueValue();
        projectIds.push(pid);
        /* project_name first. The old script tried name, title
           and short_description ahead of it, which is why some
           rows showed a sys_id looking string. */
        projectName[pid] = pick(pj, ['project_name', 'short_description']) || pj.getValue('number');
      }
    }

  } catch (e) {
    gs.error('[Reimbursements] scope: ' + e.message);
  }

  /* a project can be passed in to narrow the page to one */
  var onlyProject = $sp.getParameter('sys_id') || '';
  if (onlyProject && projectIds.indexOf(onlyProject) === -1) onlyProject = '';

  data.onlyProject = onlyProject;
  data.onlyProjectName = onlyProject ? projectName[onlyProject] : '';


  /* ============================================================
     CLAIMS
     ============================================================ */

  data.claims = [];

  var counts = { all: 0, submitted: 0, review: 0, approved: 0, paid: 0, rejected: 0 };
  var value  = { submitted: 0, review: 0, approved: 0, paid: 0, rejected: 0 };

  var payTypes = {
    advance: 0, reimbursement: 0, final: 0, partial: 0, cash: 0, accrual: 0
  };

  var monthMap = {};
  var payDays = [];
  var projectsSeen = {};

  try {

    if (projectIds.length) {

      var gr = new GlideRecordSecure(CLAIM);

      if (onlyProject) gr.addQuery('project', onlyProject);
      else gr.addQuery('project', 'IN', projectIds.join(','));

      gr.orderByDesc('sys_created_on');
      gr.setLimit(300);
      gr.query();

      while (gr.next()) {

        var st = statusOf(gr.getValue('status'));
        var amount = money2(gr, ['amount_requested']);
        var pid2 = gr.getValue('project');
        var created = gr.getValue('sys_created_on');

        projectsSeen[pid2] = true;

        counts.all++;
        counts[st.key]++;
        value[st.key] += amount;

        /* six month series, claimed against paid */
        if (created) {
          var g = new GlideDateTime(created);
          var mk = g.getYearLocalTime() + '-' + ('0' + g.getMonthLocalTime()).slice(-2);
          if (!monthMap[mk]) monthMap[mk] = { claimed: 0, paid: 0 };

          /* rejected claims are left out of the claimed line for
             the same reason they are left out of the headline */
          if (st.key !== 'rejected') monthMap[mk].claimed += amount;
          if (st.key === 'paid')     monthMap[mk].paid += amount;
        }

        /* how long payment actually takes, which the old script
           worked out and then never showed anyone */
        if (st.key === 'paid') {
          var a = toGDT(created);
          var b = toGDT(gr.getValue('sys_updated_on'));
          if (a && b) {
            var days = Math.round((b.getNumericValue() - a.getNumericValue()) / 86400000);
            if (days >= 0) payDays.push(days);
          }
        }

        var isAdvance       = bool(gr, 'advance');
        var isReimbursement = bool(gr, 'reimbursement');
        var isFinal         = bool(gr, 'final');
        var isPartial       = bool(gr, 'partial');
        var isCash          = bool(gr, 'cash');
        var isAccrual       = bool(gr, 'accrual');

        if (isAdvance)       payTypes.advance++;
        if (isReimbursement) payTypes.reimbursement++;
        if (isFinal)         payTypes.final++;
        if (isPartial)       payTypes.partial++;
        if (isCash)          payTypes.cash++;
        if (isAccrual)       payTypes.accrual++;

        data.claims.push({
          sysId  : gr.getUniqueValue(),
          number : gr.getValue('number'),
          project: projectName[pid2] || gr.getDisplayValue('project'),
          projectId: pid2,
          applicant: gr.getDisplayValue('applicant'),
          program  : gr.getDisplayValue('program'),

          status   : st.key,
          statusLabel: st.label,
          tone     : st.tone,
          stage    : st.stage,

          amount     : amount,
          amountText : money(amount),
          amountShort: short(amount),

          from   : fmtDate(pick(gr, ['from'])),
          to     : fmtDate(pick(gr, ['to'])),
          created: fmtDate(created),

          summary: pick(gr, ['short_description']),
          notes  : text(pick(gr, ['description'])),

          /* type of payment requested */
          types: {
            advance      : isAdvance,
            reimbursement: isReimbursement,
            final        : isFinal,
            partial      : isPartial,
            cash         : isCash,
            accrual      : isAccrual
          },

          /* funding and reporting details */
          funding: {
            partialRequest: pick(gr, ['partial_payment_request_number']),
            assistanceId  : pick(gr, ['financial_assistance_identification_number']),
            federalGrant  : pick(gr, ['federal_grant_or_other_identifying_number_assigned_by_federal_agency']),
            employerId    : pick(gr, ['employer_identification_number'])
          },

          /* computation of amount of reimbursements */
          comp: {
            outlays      : money(money2(gr, ['total_program_outlays_to_date'])),
            income       : money(money2(gr, ['cumulative_program_income'])),
            netOutlays   : money(money2(gr, ['net_program_outlays'])),
            estCash      : money(money2(gr, ['estimated_net_cash_outlays_for_advance_period'])),
            totalSum     : money(money2(gr, ['total_sum_of_net_program_outlays'])),
            nonFederal   : money(money2(gr, ['non_federal_share_of_amount'])),
            federal      : money(money2(gr, ['federal_share_of_amount'])),
            paidBefore   : money(money2(gr, ['federal_payments_previously_requested'])),
            nowRequested : money(money2(gr, ['federal_share_now_requested'])),
            month1       : money(money2(gr, ['request_1st_month'])),
            month2       : money(money2(gr, ['request_2nd_month'])),
            month3       : money(money2(gr, ['request_3rd_month']))
          },

          /* alternate computation for advances only */
          alt: {
            cashOutlays: money(money2(gr, ['estimated_federal_cash_outlays_that_will_be_made_during_period_covered_by_the_ad'])),
            cashOnHand : money(money2(gr, ['estimated_balance_of_federal_cash_on_hand_as_of_beginning_of_advance_period']))
          },

          files: []
        });
      }
    }

  } catch (e) {
    gs.error('[Reimbursements] read: ' + e.message);
  }


  /* ---------- attachments, in one query ---------- */
  try {
    if (data.claims.length) {

      var ids = [];
      var byId = {};

      for (var k = 0; k < data.claims.length; k++) {
        ids.push(data.claims[k].sysId);
        byId[data.claims[k].sysId] = data.claims[k];
      }

      var at = new GlideRecordSecure('sys_attachment');
      at.addQuery('table_name', CLAIM);
      at.addQuery('table_sys_id', 'IN', ids.join(','));
      at.orderByDesc('sys_created_on');
      at.query();

      while (at.next()) {
        var owner = byId[at.getValue('table_sys_id')];
        if (!owner) continue;
        owner.files.push({
          sysId: at.getUniqueValue(),
          name : at.getValue('file_name'),
          size : parseInt(at.getValue('size_bytes') || 0, 10),
          url  : '/sys_attachment.do?sys_id=' + at.getUniqueValue()
        });
      }
    }
  } catch (e) {
    gs.info('[Reimbursements] attachments unavailable: ' + e.message);
  }

  data.counts = counts;


  /* ============================================================
     THE FIGURES
     ============================================================ */

  /* Rejected money is not in flight, so it is not part of what
     has been claimed. It gets its own tile instead. */
  var inFlight = value.submitted + value.review + value.approved + value.paid;
  var decided  = value.approved + value.paid;
  var waiting  = value.submitted + value.review;

  var avgDays = 0;
  if (payDays.length) {
    var sum = 0;
    for (var d = 0; d < payDays.length; d++) sum += payDays[d];
    avgDays = Math.round(sum / payDays.length);
  }

  var projectCount = 0;
  for (var ps in projectsSeen) projectCount++;

  data.headline = counts.all + ' ' +
    (counts.all === 1 ? gs.getMessage('claim') : gs.getMessage('claims')) +
    '  ·  ' + short(inFlight) + ' ' + gs.getMessage('claimed') +
    '  ·  ' + short(value.paid) + ' ' + gs.getMessage('paid');

  data.tiles = [
    {
      key  : 'claimed',
      label: gs.getMessage('Claimed to date'),
      value: short(inFlight),
      note : counts.all + ' ' + gs.getMessage('claims across') + ' ' + projectCount + ' ' +
             (projectCount === 1 ? gs.getMessage('project') : gs.getMessage('projects')) +
             (value.rejected ? '  ·  ' + short(value.rejected) + ' ' + gs.getMessage('rejected, excluded') : '')
    },
    {
      key  : 'paid',
      label: gs.getMessage('Paid'),
      value: short(value.paid),
      /* of what was decided, not of everything ever submitted */
      note : decided
               ? Math.round((value.paid / decided) * 100) + '% ' + gs.getMessage('of approved value')
               : gs.getMessage('nothing approved yet')
    },
    {
      key  : 'waiting',
      label: gs.getMessage('Awaiting a decision'),
      value: short(waiting),
      note : (counts.submitted + counts.review) + ' ' +
             ((counts.submitted + counts.review) === 1 ? gs.getMessage('claim') : gs.getMessage('claims')) +
             ' ' + gs.getMessage('with the program office'),
      alert: (counts.submitted + counts.review) > 0
    },
    {
      key  : 'speed',
      label: gs.getMessage('Typical time to payment'),
      /* an average over nothing is not a number */
      value: payDays.length ? avgDays + ' ' + gs.getMessage('days') : '—',
      note : payDays.length
               ? gs.getMessage('measured across') + ' ' + payDays.length + ' ' + gs.getMessage('paid claims')
               : gs.getMessage('nothing has been paid yet')
    }
  ];


  /* ---------- the money pipeline ----------
     Four stages in the order money actually moves. Rejected sits
     outside it, because a rejected claim did not stop at a stage,
     it left. */
  function stageRow(key, label, count, amount) {
    return {
      key   : key,
      label : label,
      count : count,
      amount: amount,
      text  : short(amount),
      width : inFlight ? Math.max(amount > 0 ? 4 : 0, Math.round((amount / inFlight) * 100)) : 0
    };
  }

  data.pipeline = [
    stageRow('submitted', STATUS['submitted'].label, counts.submitted, value.submitted),
    stageRow('review',    STATUS['in review'].label, counts.review,    value.review),
    stageRow('approved',  STATUS['approved'].label,  counts.approved,  value.approved),
    stageRow('paid',      STATUS['paid'].label,      counts.paid,      value.paid)
  ];

  data.rejected = {
    count : counts.rejected,
    amount: value.rejected,
    text  : short(value.rejected)
  };


  /* ---------- six months ---------- */
  var monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  data.months = [];
  var peak = 0;

  for (var i = 5; i >= 0; i--) {
    var gm = new GlideDateTime();
    gm.addMonthsLocalTime(-i);
    var mi = gm.getMonthLocalTime() - 1;
    var key = gm.getYearLocalTime() + '-' + ('0' + (mi + 1)).slice(-2);
    var row = monthMap[key] || { claimed: 0, paid: 0 };

    if (row.claimed > peak) peak = row.claimed;
    if (row.paid > peak) peak = row.paid;

    data.months.push({
      label  : monthNames[mi],
      claimed: row.claimed,
      paid   : row.paid,
      claimedText: short(row.claimed),
      paidText   : short(row.paid)
    });
  }

  for (var mm = 0; mm < data.months.length; mm++) {
    data.months[mm].claimedPct = peak ? Math.round((data.months[mm].claimed / peak) * 100) : 0;
    data.months[mm].paidPct    = peak ? Math.round((data.months[mm].paid / peak) * 100) : 0;
  }

  data.monthPeak = short(peak);
  data.monthHalf = short(peak / 2);
  data.hasMonthData = peak > 0;


  /* ---------- how you are asking to be paid ----------
     Six booleans on the form that nothing has ever reported on.
     Whether claims are advances or reimbursements, and whether
     any are marked final, is worth knowing at a glance. */
  var typeRows = [
    { key: 'advance',       label: gs.getMessage('Advance'),       count: payTypes.advance },
    { key: 'reimbursement', label: gs.getMessage('Reimbursement'), count: payTypes.reimbursement },
    { key: 'partial',       label: gs.getMessage('Partial'),       count: payTypes.partial },
    { key: 'final',         label: gs.getMessage('Final'),         count: payTypes.final },
    { key: 'cash',          label: gs.getMessage('Cash basis'),    count: payTypes.cash },
    { key: 'accrual',       label: gs.getMessage('Accrual basis'), count: payTypes.accrual }
  ];

  var typePeak = 0;
  for (var tp = 0; tp < typeRows.length; tp++) {
    if (typeRows[tp].count > typePeak) typePeak = typeRows[tp].count;
  }

  data.payTypes = [];
  for (var tq = 0; tq < typeRows.length; tq++) {
    data.payTypes.push({
      key  : typeRows[tq].key,
      label: typeRows[tq].label,
      count: typeRows[tq].count,
      width: typePeak ? Math.round((typeRows[tq].count / typePeak) * 100) : 0
    });
  }

  data.hasTypeData = typePeak > 0;


  /* ============================================================
     COPY
     ============================================================ */

  data.t = {
    title : opt('label_title', gs.getMessage('Reimbursements')),
    search: gs.getMessage('Search by claim, project or amount'),

    pipeTitle: gs.getMessage('Where the money is'),
    pipeHint : gs.getMessage('Every claim in flight, by the stage it has reached'),
    pipeEmpty: gs.getMessage('No claims yet, so there is nothing in flight.'),
    rejected : gs.getMessage('rejected and out of the pipeline'),

    monthTitle: gs.getMessage('Claimed against paid'),
    monthHint : gs.getMessage('The last six months. The gap between the two bars is money still owed to you.'),
    monthEmpty: gs.getMessage('Nothing claimed in the last six months.'),
    keyClaimed: gs.getMessage('Claimed'),
    keyPaid   : gs.getMessage('Paid'),

    typeTitle: gs.getMessage('How you have asked to be paid'),
    typeHint : gs.getMessage('Claims can carry more than one of these, so the counts overlap'),
    typeEmpty: gs.getMessage('No payment types recorded yet.'),

    listTitle: gs.getMessage('All claims'),
    listHint : gs.getMessage('Newest first'),
    newClaim : gs.getMessage('New claim'),

    tabAll      : gs.getMessage('All'),
    tabSubmitted: gs.getMessage('Submitted'),
    tabReview   : gs.getMessage('In review'),
    tabApproved : gs.getMessage('Approved'),
    tabPaid     : gs.getMessage('Paid'),
    tabRejected : gs.getMessage('Rejected'),

    colClaim  : gs.getMessage('Claim'),
    colProject: gs.getMessage('Project'),
    colPeriod : gs.getMessage('Period'),
    colAmount : gs.getMessage('Amount'),
    colFiled  : gs.getMessage('Filed'),
    colState  : gs.getMessage('State'),
    colAction : gs.getMessage('Action'),

    view : gs.getMessage('View'),
    close: gs.getMessage('Close'),
    clear: gs.getMessage('Clear'),

    mPayment    : gs.getMessage('Type of payment'),
    mFunding    : gs.getMessage('Funding and reporting'),
    mComputation: gs.getMessage('Computation'),
    mAlternate  : gs.getMessage('Alternate computation'),
    mFiles      : gs.getMessage('Attachments'),

    mNumber   : gs.getMessage('Number'),
    mProject  : gs.getMessage('Project'),
    mApplicant: gs.getMessage('Applicant'),
    mProgram  : gs.getMessage('Program'),
    mAmount   : gs.getMessage('Amount requested'),
    mSummary  : gs.getMessage('Short description'),
    mNotes    : gs.getMessage('Description'),
    mFiled    : gs.getMessage('Filed'),
    mPeriod   : gs.getMessage('Period covered'),
    mFrom     : gs.getMessage('From'),
    mTo       : gs.getMessage('To'),

    mAdvance      : gs.getMessage('Advance'),
    mReimbursement: gs.getMessage('Reimbursement'),
    mFinal        : gs.getMessage('Final'),
    mPartial      : gs.getMessage('Partial'),
    mCash         : gs.getMessage('Cash'),
    mAccrual      : gs.getMessage('Accrual'),

    mPartialReq  : gs.getMessage('Partial payment request number'),
    mAssistance  : gs.getMessage('Financial assistance identification number'),
    mFederalGrant: gs.getMessage('Federal grant or identifying number'),
    mEmployerId  : gs.getMessage('Employer identification number'),

    mOutlays     : gs.getMessage('Total program outlays to date'),
    mIncome      : gs.getMessage('Less cumulative program income'),
    mNetOutlays  : gs.getMessage('Net program outlays'),
    mEstCash     : gs.getMessage('Estimated net cash outlays for advance period'),
    mTotalSum    : gs.getMessage('Total of net outlays and estimated cash outlays'),
    mNonFederal  : gs.getMessage('Non-federal share of amount'),
    mFederal     : gs.getMessage('Federal share of amount'),
    mPaidBefore  : gs.getMessage('Federal payments previously requested'),
    mNowRequested: gs.getMessage('Federal share now requested'),
    mMonth1      : gs.getMessage('Request first month'),
    mMonth2      : gs.getMessage('Request second month'),
    mMonth3      : gs.getMessage('Request third month'),

    mCashOutlays: gs.getMessage('Estimated federal cash outlays during the advance period'),
    mCashOnHand : gs.getMessage('Estimated balance of federal cash on hand at the start'),

    mNone     : gs.getMessage('Not provided'),
    mNoFiles  : gs.getMessage('Nothing attached'),
    mNotTicked: gs.getMessage('None of these were ticked'),

    emptyTitle: gs.getMessage('No claims yet'),
    emptyText : gs.getMessage('Claims are filed against a project. Once one is approved and you have spent against it, the money comes back through here.'),
    emptyBtn  : gs.getMessage('File your first claim'),

    noProjects    : gs.getMessage('You have no projects yet'),
    noProjectsText: gs.getMessage('Reimbursement claims are filed against a project, and a project opens once you accept an award.'),

    noMatch    : gs.getMessage('Nothing matches this filter'),
    noMatchText: gs.getMessage('Try another tab, or clear the search.')
  };

  data.hasProjects = projectIds.length > 0;
  data.pageSize = parseInt(opt('page_size', '10'), 10) || 10;

})();
